public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static class TreeNode {
        long val;
        TreeNode left, right;

        TreeNode(long val) {
            this.val = val;
        }
    }

    // Builds a binary tree from a level-order list of words; "N" marks a missing child.
    static TreeNode buildTree(String[] vals) {
        if (vals.length == 0 || vals[0].equals("N")) return null;
        TreeNode root = new TreeNode(Long.parseLong(vals[0]));
        ArrayList<TreeNode> queue = new ArrayList<>();
        queue.add(root);
        int head = 0, i = 1;
        while (head < queue.size() && i < vals.length) {
            TreeNode node = queue.get(head++);
            if (!vals[i].equals("N")) {
                node.left = new TreeNode(Long.parseLong(vals[i]));
                queue.add(node.left);
            }
            i++;
            if (i < vals.length && !vals[i].equals("N")) {
                node.right = new TreeNode(Long.parseLong(vals[i]));
                queue.add(node.right);
            }
            i++;
        }
        return root;
    }

    // Prints a tree in the same level-order form ("empty" for no tree).
    static void printTree(TreeNode root) {
        if (root == null) {
            System.out.println("empty");
            return;
        }
        ArrayList<String> out = new ArrayList<>();
        ArrayList<TreeNode> queue = new ArrayList<>();
        queue.add(root);
        int head = 0;
        while (head < queue.size()) {
            TreeNode node = queue.get(head++);
            if (node == null) {
                out.add("N");
            } else {
                out.add(String.valueOf(node.val));
                queue.add(node.left);
                queue.add(node.right);
            }
        }
        while (!out.isEmpty() && out.get(out.size() - 1).equals("N")) out.remove(out.size() - 1);
        System.out.println(String.join(" ", out));
    }


    static List<List<Long>> vertical(TreeNode root) {
        TreeMap<Integer, List<long[]>> cells = new TreeMap<>();
        ArrayList<Object[]> stack = new ArrayList<>();
        stack.add(new Object[] {root, 0, 0});
        while (!stack.isEmpty()) {
            Object[] top = stack.remove(stack.size() - 1);
            TreeNode node = (TreeNode) top[0];
            int col = (Integer) top[1], row = (Integer) top[2];
            cells.computeIfAbsent(col, k -> new ArrayList<>()).add(new long[] {row, node.val});
            if (node.left != null) stack.add(new Object[] {node.left, col - 1, row + 1});
            if (node.right != null) stack.add(new Object[] {node.right, col + 1, row + 1});
        }
        List<List<Long>> result = new ArrayList<>();
        for (List<long[]> column : cells.values()) {
            column.sort((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
            List<Long> values = new ArrayList<>();
            for (long[] cell : column) values.add(cell[1]);
            result.add(values);
        }
        return result;
    }

